// Nursing Assisting Practice Test 4. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and covering topics not used in Practice Tests 1–3.
import {q, mix} from './q.js';
const DUG='Dugan, Nursing Assisting: A Foundation in Caregiving', ROE='Roe, The Nursing Assistant: Essentials of Holistic Care';
const ROLE='Nursing Assistant Roles and Responsibilities', AP='Anatomy and Physiology', INF='Infection Control/Safety', COMM='Communication/Culture', CARE='Providing and Reporting Care', DIS='Disabilities and Disorders';

export default {
 id:'nursing-assisting-4',
 event:'Nursing Assisting',
 title:'Practice Test 4',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Dugan’s Nursing Assisting: A Foundation in Caregiving and Roe’s The Nursing Assistant',
 plan:[{area:ROLE,weight:6},{area:AP,weight:20},{area:INF,weight:14},{area:COMM,weight:10},{area:CARE,weight:30},{area:DIS,weight:20}],
 questions:mix([
  q(ROLE,'Which member of the care team develops and updates the resident’s nursing care plan?','The registered nurse',['The nursing assistant','The dietary aide','The resident’s visitor'],'A','The NA contributes observations, but the RN is responsible for the care plan.',DUG),
  q(ROLE,'A nursing assistant sees another NA roughly handling a resident. What should she do?','Report it to the nurse right away',['Wait to see if it happens again','Tell the resident to stay quiet','Post about it on social media'],'B','Every staff member must report suspected abuse immediately to protect residents.',DUG),
  q(ROLE,'Which action protects a resident’s right to privacy?','Closing the curtain during care',['Leaving the door open during baths','Reading the resident’s mail aloud','Discussing care in the hallway'],'C','Privacy includes the body, personal belongings, mail and health information.',DUG),
  q(AP,'Which structure connects muscle to bone?','Tendon',['Ligament','Cartilage','Bursa'],'D','Ligaments connect bone to bone, while tendons connect muscle to bone.',DUG),
  q(AP,'Which part of the nervous system controls automatic functions such as heart rate?','Autonomic nervous system',['Somatic nervous system','Cerebral cortex only','Peripheral sensory nerves'],'A','The autonomic system controls heart rate, breathing and digestion without conscious control.',DUG),
  q(AP,'Where are the vocal cords located?','Larynx',['Trachea','Bronchi','Pharynx'],'B','The larynx, or voice box, sits at the top of the trachea and holds the vocal cords.',DUG),
  q(AP,'Which blood vessels have walls thin enough for oxygen to pass into tissues?','Capillaries',['Arterioles','Venules','The aorta'],'C','Capillaries connect the smallest arteries to the smallest veins.',DUG),
  q(AP,'Which organ removes old red blood cells and helps fight infection?','Spleen',['Bladder','Esophagus','Ovary'],'D','The spleen is part of the lymphatic system and filters the blood.',DUG),
  q(AP,'Which hormone helps the body respond to stress and is made by the adrenal glands?','Cortisol',['Insulin','Estrogen','Melatonin'],'A','Cortisol raises blood sugar, helps control inflammation and supports the stress response.',DUG),
  q(AP,'Where does the absorption of water mainly happen in the digestive tract?','Large intestine',['Mouth and tongue','Esophagus','Stomach lining'],'B','The large intestine absorbs most remaining water and forms solid stool.',DUG),
  q(AP,'Which structure in the ear helps with balance?','Semicircular canals',['Outer ear lobe','Tympanic membrane','Ear canal glands'],'C','Fluid in the semicircular canals senses head movement and position.',DUG),
  q(AP,'Which reproductive organ produces eggs in females?','Ovaries',['Uterus','Vagina','Cervix'],'D','The ovaries also make the hormones estrogen and progesterone.',DUG),
  q(AP,'Which change in the cardiovascular system is common with aging?','The heart pumps less efficiently',['The heart grows much stronger','Blood vessels become more elastic','Blood pressure always drops'],'A','Older adults may tire more easily and need rest between activities.',DUG),
  q(INF,'Which item of PPE is put on last?','Gloves',['Gown','Mask','Goggles'],'B','Gloves go on last so they cover the cuffs of the gown and stay clean for care.',DUG),
  q(INF,'Which disease requires droplet precautions?','Pertussis',['Tuberculosis','Chickenpox','Salmonella'],'C','Droplets travel about 6 feet, so a surgical mask is worn within that distance.',DUG),
  q(INF,'Which practice is correct for oxygen safety in a resident’s room?','No smoking or open flames',['Use wool blankets on the bed','Keep candles lit for comfort','Use electric razors near the tank'],'D','Oxygen makes fires burn hotter and faster, so ignition sources are removed.',DUG),
  q(INF,'What should be done with a needle found in a resident’s bed linens?','Place it in a sharps container',['Recap it using both hands','Throw it in the regular trash','Leave it for housekeeping staff'],'A','Report the found needle so the nurse can learn how it got there.',DUG),
  q(INF,'Which is the correct way to use a gait belt during ambulation?','Snug at the waist, over clothes',['Loose around the resident’s neck','Tight around the resident’s chest','Over bare skin at the hips only'],'B','The belt should be snug enough that only two fingers fit under it, and it is applied over clothing.',DUG),
  q(INF,'Which type of restraint alternative helps a resident who tries to get out of bed alone?','A bed or chair alarm',['A locked room door','A tight vest restraint','A sheet tied to the rails'],'C','Alternatives such as alarms and frequent checks are tried before any restraint.',DUG),
  q(INF,'What should the nursing assistant do if a resident is choking and cannot speak?','Give abdominal thrusts and call for help',['Give the resident a glass of water','Pat the resident gently on the arm','Wait to see if the resident recovers'],'D','Abdominal thrusts push air out of the lungs to dislodge the object.',DUG),
  q(COMM,'A resident who speaks little English seems confused about care. What should the NA do?','Use an interpreter or picture cards',['Speak louder in English only','Skip the care for that day','Ask another resident to translate'],'A','Clear communication protects safety and the resident’s right to understand care.',DUG),
  q(COMM,'Which statement is the best way to report an observation?','“Mr. Lee’s pulse is 112 and irregular.”',['“Mr. Lee seems a little off today.”','“I think Mr. Lee is just tired.”','“Mr. Lee is being difficult again.”'],'B','Reports should be specific, objective and timely, using facts and measurements rather than opinions.',DUG),
  q(COMM,'Which behavior respects a resident’s cultural beliefs about modesty?','Assigning a same-gender caregiver if possible',['Leaving the door open during personal care','Refusing to discuss the resident’s request','Telling the resident to get over it'],'C','Many cultures and religions value modesty during personal care.',DUG),
  q(COMM,'A resident with dementia calls the NA by her daughter’s name. What should the NA do?','Respond kindly without arguing',['Correct her firmly each time','Ignore her until she stops','Tell her she is wrong'],'D','Arguing increases confusion and distress in residents with dementia.',DUG),
  q(COMM,'Which approach helps when talking with a resident who is angry?','Listen calmly and acknowledge feelings',['Argue to prove your own point','Walk away without saying a word','Raise your voice to match theirs'],'A','Staying calm and listening helps defuse anger and keeps the resident and staff safe.',DUG),
  q(CARE,'What is the correct way to provide catheter care?','Clean from the meatus outward',['Clean toward the body from the bag','Pull the catheter to check placement','Disconnect the tubing to clean it'],'B','Cleaning away from the body keeps germs from entering the bladder.',DUG),
  q(CARE,'How should a nursing assistant measure a resident’s weight with a standing scale?','Same time and clothing each day',['Different times of day each time','With heavy shoes and a coat on','Only once each year'],'C','Weighing at the same time with the same clothing makes true weight changes easier to spot.',DUG),
  q(CARE,'Which action is correct when transferring a resident from bed to wheelchair?','Lock the wheels before the transfer',['Leave the wheels unlocked for movement','Pull the resident up by the arms','Twist your back while lifting'],'D','Locked wheels keep the chair from rolling away during transfers.',DUG),
  q(CARE,'Which position helps a resident with a pressure injury on the sacrum?','30-degree side-lying',['Flat on the back','High Fowler’s','Sitting for hours'],'A','The 30-degree tilt takes pressure off the sacrum and hip bones.',DUG),
  q(CARE,'Which observation should be reported after a resident’s shower?','A new open area on the heel',['Clean, dry and intact skin','Hair washed and combed','Fresh clothes put on'],'B','New skin breakdown, such as an open heel, needs the nurse’s assessment right away.',DUG),
  q(CARE,'Why is it important to give mouth care to a resident who is NPO?','The mouth dries out and germs grow',['NPO residents never need mouth care','It replaces the resident’s meals','It helps them gain weight quickly'],'C','NPO means nothing by mouth, so the mouth is not cleaned by eating or drinking.',DUG),
  q(CARE,'Which action helps prevent contractures?','Range-of-motion exercises',['Keeping joints bent all day','Limiting all movement','Removing splints early'],'D','Contractures are permanent shortening of muscles from lack of movement.',DUG),
  q(CARE,'What is the correct way to collect a stool specimen?','Use a clean container, avoid urine and paper',['Mix urine into the sample for volume','Use toilet paper to collect the stool','Leave the sample uncovered for hours'],'A','Urine and toilet paper can change stool test results, so the specimen is collected in a clean container.',DUG),
  q(CARE,'Which observation should be reported while giving a resident a bed bath?','A reddened area over the hip',['Warm, clean, dry skin','Hair that needs combing','Fingernails that are short'],'B','Redness over a bony area may be the start of a pressure injury.',DUG),
  q(CARE,'How should an NA help a resident who uses a cane?','Stand on the weak side, slightly behind',['Walk several steps ahead of the resident','Stand on the strong side only','Hold the cane for the resident while walking'],'C','Standing on the weak side lets the NA support the resident if they lose balance.',DUG),
  q(CARE,'Which practice is correct when caring for a resident who is dying?','Keep providing gentle care and talk to them',['Stop all care and leave the room','Speak about them as if they are gone','Keep the room cold and very dark'],'D','Hearing is believed to be one of the last senses lost, so keep talking gently to the resident.',DUG),
  q(CARE,'What should an NA do after a resident dies, as directed by the nurse?','Provide post-mortem care with respect',['Leave the body until the next shift','Remove all dentures and throw away','Tell the family it is their fault'],'A','Post-mortem care follows facility policy and the family’s cultural needs.',DUG),
  q(CARE,'Which is the correct way to apply a warm compress?','Check the temperature and skin often',['Leave it on all day without checks','Use water as hot as possible','Put it on numb skin without checks'],'B','Older adults and people with poor sensation burn easily, so check the skin often.',DUG),
  q(CARE,'What is the correct procedure for ambulating a resident after long bed rest?','Dangle at the bedside first',['Stand up as fast as possible','Walk without any help','Skip checking for dizziness'],'C','Dangling helps the body adjust and prevents fainting from low blood pressure.',DUG),
  q(CARE,'Which action is correct when serving meal trays?','Check the diet card with the resident’s name',['Serve the trays in any order','Let residents trade their special diets','Remove the diet card before serving'],'D','Checking prevents residents from receiving food that could harm them.',DUG),
  q(DIS,'Which condition causes thick, sticky mucus and is often diagnosed in childhood?','Cystic fibrosis',['Osteoporosis','Cataracts','Shingles (zoster)'],'A','Cystic fibrosis is inherited and mainly affects the lungs and digestive system.',DUG),
  q(DIS,'Which finding is common in a resident with hyperglycemia?','Thirst and frequent urination',['Cold, clammy, shaky skin','Sudden sweating and hunger','A very low blood sugar'],'B','High blood sugar pulls water out of the body through the kidneys.',DUG),
  q(DIS,'Which condition is caused by blocked blood flow in the brain?','Ischemic stroke',['Asthma attack','Gout flare','Kidney stone'],'C','Ischemic strokes are the most common type and need emergency care.',DUG),
  q(DIS,'Which care is important for a resident with an ostomy?','Check the stoma color and skin',['Remove the pouch every hour','Limit all fluids for the day','Keep the stoma covered in cream'],'D','A healthy stoma is pink or red and moist; report pale, dark or bleeding stomas to the nurse.',DUG),
  q(DIS,'Which disease attacks the immune system and is spread through blood and body fluids?','HIV',['Influenza','Common cold','Pinkeye'],'A','Standard precautions protect caregivers from bloodborne diseases like HIV.',DUG),
  q(DIS,'Which condition causes the lungs to lose elasticity and trap air?','Emphysema',['Sinusitis','Strep throat','Hay fever'],'B','Emphysema is a type of COPD, often caused by smoking, that damages the air sacs.',DUG),
  q(DIS,'Which condition is a disorder in which the heart cannot pump enough blood?','Heart failure',['Varicose veins','Hemorrhoids','Nosebleeds'],'C','Common signs include swelling, shortness of breath and weight gain.',DUG),
  q(DIS,'Which condition is a developmental disorder affecting social communication?','Autism spectrum disorder',['Rheumatoid arthritis','Bacterial pneumonia','Hepatitis A infection'],'D','People with autism may prefer routines and be sensitive to noise or touch.',DUG),
  q(DIS,'Which condition causes the body to lose bone density, raising fracture risk?','Osteoporosis',['Bronchitis','Glaucoma','Diabetes type 2'],'A','Calcium, vitamin D and weight-bearing exercise help protect bones.',DUG),
  q(DIS,'Which is a common sign of an anxiety disorder?','Restlessness and fast heartbeat',['Calm mood and slow heart rate','Lots of energy and happiness','Steady sleep every night'],'B','Anxiety can cause worry, fast breathing, sweating and trouble sleeping.',DUG)
 ],8222)
};
